 } public function translate_term_name($data, $taxonomy, $args) { if ( filter_var($this->options->qc_translate_term_name_enabled, FILTER_VALIDATE_BOOLEAN) && in_array($args, $this->options->qc_translate_taxonomies) ) { $data['name'] = apply_filters( 'qqworld-collector-do-translate', $data['name'] ); } return $data; } public function translate_name($name) { $name = urldecode($name); switch ($this->options->qc_translate_post_name_method) { case 'pinyin': $this->includes_lib('pinyin'); $pinyin = new \Overtrue\Pinyin\Pinyin(); $results = $pinyin->convert($name); do_action( 'qqworld-collector-log', $this->log_id, 'Translate post name to pinyin (original $name):', print_r($name, true) ); $name = implode('-', $results); do_action( 'qqworld-collector-log', $this->log_id, 'Translate post name to pinyin (pinyin $name):', print_r($name, true) ); break; case 'english': $mode = in_array($this->options->qc_translate_mode, array('aliyun', 'baidu', 'google', 'deepl', 'youdao')) ? $this->options->qc_translate_mode : 'google-free'; $from = apply_filters( 'qqworld-collector-translate-name-from', 'auto' ); $lang = $this->options->qc_translate_mode == 'deepl' ? 'en-US' : 'en'; $new_name = apply_filters( 'qqworld-collector-translate', $name, $from, $lang, $mode ); if ($new_name) { do_action( 'qqworld-collector-log', $this->log_id, 'Translate post name to english (original $name):', print_r($name, true) ); $name = $new_name; do_action( 'qqworld-collector-log', $this->log_id, 'Translate post name to english (english $name):', print_r($name, true) ); } break; case 'md5': $length = $this->options->qc_translate_post_name_max_length < 32 && $this->options->qc_translate_post_name_max_length > 0 ? $this->options->qc_translate_post_name_max_length : 32; if (!preg_match('/\w{'.$length.'}/i', $name)) { do_action( 'qqworld-collector-log', $this->log_id, 'Translate post name to md5 (original $name):', print_r($name, true) ); $name = md5($name); do_action( 'qqworld-collector-log', $this->log_id, 'Translate post name to md5 (md5 $name):', print_r($name, true) ); } break; } if ($this->options->qc_translate_post_name_max_length > 0) $name = mb_substr($name, 0, $this->options->qc_translate_post_name_max_length, 'utf-8'); $name = str_replace(array(' ', '?', "'", ',', '.', '!', ':', '：', '(', ')'), array('-', '', '', '', '', '', '', '', '', ''), trim($name)); $name = preg_replace(array('/[\-\|]*$/', '/-{2,}/'), array('', '-'), $name); $name = strtolower($name); return $name; } public function translate_post_name($data, $postarr) { if ( !in_array($data['post_status'], array('auto-draft', 'trash', 'inherit')) && filter_var($this->options->qc_translate_post_name_enabled, FILTER_VALIDATE_BOOLEAN) && in_array($data['post_type'], $this->options->qc_translate_post_name_post_types) ) { $data['post_name'] = $this->translate_name($data['post_name']); } return $data; } public function translate_term_slug($data, $taxonomy, $args) { $taxonomy = is_string($args) ? $args : $args['taxonomy']; if ( filter_var($this->options->qc_translate_term_slug_enabled, FILTER_VALIDATE_BOOLEAN) && in_array($taxonomy, $this->options->qc_translate_term_slug_taxonomies) ) { $data['slug'] = $this->translate_name(urldecode($data['slug'])); $data['slug'] = wp_unique_term_slug($data['slug'], (object) $args); } return $data; } public function translate_filename($filename, $args) { if ( filter_var($this->options->qc_translate_filename_enabled, FILTER_VALIDATE_BOOLEAN) ) { $filename = $this->translate_name($filename); } return $filename; } public function external_sdk($sdks) { $sdks[$this->module]['items']['aliyun'] = array( 'label' => __('Aliyun Machine Translation', $this->text_domain), 'path' => WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'alibabacloud' . DIRECTORY_SEPARATOR . 'autoload.php', 'download' => 'alibabacloud.zip', 'extract' => true, 'manual' => sprintf(__('Please download <a href="%s" target="_blank"><strong>%s</strong></a> and unzip it to directory <strong>%s</strong>.', $this->text_domain), 'https://pan.qqworld.org/QQWorld%E6%94%B6%E8%97%8F%E5%AE%B6%E8%B1%AA%E5%8D%8E%E7%89%88/%E8%BD%AF%E4%BB%B6%E5%BC%80%E5%8F%91%E5%B7%A5%E5%85%B7%E5%8C%85%EF%BC%88SDK%EF%BC%89', 'alibabacloud.zip', WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR ) ); $sdks[$this->module]['items']['tencent'] = array( 'label' => __('Tencent Machine Translation', $this->text_domain), 'path' => WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'tencentcloud' . DIRECTORY_SEPARATOR . 'autoload.php', 'download' => 'tencentcloud.zip', 'extract' => true, 'manual' => sprintf(__('Please download <a href="%s" target="_blank"><strong>%s</strong></a> and unzip it to directory <strong>%s</strong>.', $this->text_domain), 'https://pan.qqworld.org/QQWorld%E6%94%B6%E8%97%8F%E5%AE%B6%E8%B1%AA%E5%8D%8E%E7%89%88/%E8%BD%AF%E4%BB%B6%E5%BC%80%E5%8F%91%E5%B7%A5%E5%85%B7%E5%8C%85%EF%BC%88SDK%EF%BC%89', 'tencentcloud.zip', WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR ) ); $sdks[$this->module]['items']['deepl'] = array( 'label' => __('DeepL Translation', $this->text_domain), 'path' => WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR . 'deepl-php' . DIRECTORY_SEPARATOR . 'autoload.php', 'download' => 'deepl-php.zip', 'extract' => true, 'manual' => sprintf(__('Please download <a href="%s" target="_blank"><strong>%s</strong></a> and unzip it to directory <strong>%s</strong>.', $this->text_domain), 'https://pan.qqworld.org/QQWorld%E6%94%B6%E8%97%8F%E5%AE%B6%E8%B1%AA%E5%8D%8E%E7%89%88/%E8%BD%AF%E4%BB%B6%E5%BC%80%E5%8F%91%E5%B7%A5%E5%85%B7%E5%8C%85%EF%BC%88SDK%EF%BC%89', 'deepl-php.zip', WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'libs' . DIRECTORY_SEPARATOR ) ); return $sdks; } } ?>